  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Glycyrrhizin, the closest analogue sharing the glycyrrhetinic acid core and C30 carboxylate, showed only ~2.3% CSF/serum ratio after intraperitoneal dosing in rats, indicating low brain availability for this class of ionizable triterpenoid conjugates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Prednisolone-hemisuccinate, a steroid hemisuccinate with a terminal carboxylate, was detected at extremely low CSF levels, demonstrating that adding a hemisuccinate group to a steroid scaffold impairs blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Oleanolic acid derivatives bearing a C3 ester and a free C28 acid reached micromolar brain concentrations after intraperitoneal administration, showing that some triterpenoid acid esters can cross the BBB; however, these lack the additional ionizable hemisuccinate carboxylate present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is carbenoxolone, a dianionic hemisuccinate ester of glycyrrhetinic acid. The closest experimental analogue, glycyrrhizin, shows low CSF/serum distribution, and a steroid hemisuccinate also shows negligible CSF penetration. Although several triterpenoid acids/esters can be detected in brain, they lack the terminal ionizable carboxylate that dominates the query's physicochemical liabilities. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct measurement of carbenoxolone or its glycyrrhetinic acid metabolite in brain/CSF after systemic dosing",
    "Uncertainty about in vivo ester hydrolysis and whether the active metabolite glycyrrhetinic acid provides CNS exposure",
    "Lack of transporter-specific data at the BBB for this dianionic triterpenoid"
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
