    },
    {
      "applicability": "moderate",
      "card_ids": ["C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "steroid hemisuccinates"
    },
    {
      "applicability": "low",
      "card_ids": ["C03"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "oleanolic acid esters"
    }
  ],
  "revision_action": "initial"
}

